-- Separate user content. Deliberately no reads, writes or migrations of Notes.
create table public.constellation_versions(user_id uuid primary key references auth.users on delete cascade,revision bigint not null default 0);
create table public.constellation_commands(user_id uuid not null references auth.users on delete cascade,id uuid not null,request_hash bytea not null,revision bigint not null,primary key(user_id,id));
create table public.constellation_cards(id uuid primary key,user_id uuid not null references auth.users on delete cascade,payload jsonb not null,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(user_id,id));
create table public.constellation_tags(id uuid primary key,user_id uuid not null references auth.users on delete cascade,name text not null check(length(name) between 1 and 40 and name=lower(name) and name~'^[[:alnum:]_-]+$'),unique(user_id,name) deferrable initially deferred);
do $$declare t text;begin foreach t in array array['constellation_versions','constellation_commands','constellation_cards','constellation_tags'] loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('create policy owner_read on public.%I for select to authenticated using ((select auth.uid())=user_id)',t);end loop;end $$;
create function public.read_constellations() returns jsonb language plpgsql stable security invoker set search_path='' as $$begin
 if auth.uid() is null then raise exception 'Sign in required' using errcode='42501';end if;
 return jsonb_build_object('revision',coalesce((select revision from public.constellation_versions where user_id=auth.uid()),0),'state',jsonb_build_object('cards',coalesce((select jsonb_agg(payload||jsonb_build_object('id',id,'createdAt',created_at,'updatedAt',updated_at)) from public.constellation_cards where user_id=auth.uid()),'[]'),'tags',coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',name)) from public.constellation_tags where user_id=auth.uid()),'[]')));end $$;
revoke all on function public.read_constellations() from public,anon;grant execute on function public.read_constellations() to authenticated;
create function public.save_constellations(p_expected_revision bigint,p_command_id uuid,p_state jsonb) returns bigint language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();v bigint;r public.constellation_commands;h bytea;c jsonb;t jsonb;i jsonb;a jsonb;p jsonb;old public.constellation_cards;
begin
 if uid is null then raise exception 'Sign in required' using errcode='42501';end if;
 if p_command_id is null or p_expected_revision is null or jsonb_typeof(p_state->'cards') is distinct from 'array' or jsonb_typeof(p_state->'tags') is distinct from 'array' or octet_length(p_state::text)>8388608 or jsonb_array_length(p_state->'cards')>1000 or jsonb_array_length(p_state->'tags')>500 then raise exception 'Invalid board' using errcode='22023';end if;
 insert into public.constellation_versions(user_id) values(uid) on conflict do nothing;select revision into v from public.constellation_versions where user_id=uid for update;h:=sha256(convert_to(p_state::text,'UTF8'));
 select * into r from public.constellation_commands where user_id=uid and id=p_command_id;if found then if r.request_hash<>h then raise exception 'Command reused' using errcode='22023';end if;return r.revision;end if;
 if v<>p_expected_revision then raise exception 'Board changed' using errcode='40001';end if;
 if (select count(distinct value->>'id') from jsonb_array_elements(p_state->'cards'))<>jsonb_array_length(p_state->'cards') or (select count(distinct value->>'id') from jsonb_array_elements(p_state->'tags'))<>jsonb_array_length(p_state->'tags') then raise exception 'Duplicate IDs' using errcode='22023';end if;
 for t in select value from jsonb_array_elements(p_state->'tags') loop
 if exists(select 1 from public.constellation_tags where id=(t->>'id')::uuid and user_id<>uid) then raise exception 'Tag unavailable' using errcode='42501';end if;
 insert into public.constellation_tags(id,user_id,name) values((t->>'id')::uuid,uid,t->>'name') on conflict(id) do update set name=excluded.name where public.constellation_tags.user_id=uid;end loop;
 for c in select value from jsonb_array_elements(p_state->'cards') loop
 if jsonb_typeof(c->'title') is distinct from 'string' or length(c->>'title')>250 or jsonb_typeof(c->'text') is distinct from 'string' or length(c->>'text')>100000 or jsonb_typeof(c->'pinned') is distinct from 'boolean' or jsonb_typeof(c->'items') is distinct from 'array' or jsonb_array_length(c->'items')>200 or jsonb_typeof(c->'images') is distinct from 'array' or jsonb_array_length(c->'images')>8 or jsonb_typeof(c->'tagIds') is distinct from 'array' or (c->>'accent' is not null and c->>'accent' not in ('primary','secondary','pop','warm','info')) then raise exception 'Invalid card' using errcode='22023';end if;
 for i in select value from jsonb_array_elements(c->'items') loop if jsonb_typeof(i->'text') is distinct from 'string' or length(i->>'text')>1000 or jsonb_typeof(i->'complete') is distinct from 'boolean' or i->>'id' is null then raise exception 'Invalid checklist' using errcode='22023';end if;end loop;
 for i in select value from jsonb_array_elements(c->'tagIds') loop if not exists(select 1 from jsonb_array_elements(p_state->'tags') tag_entry where tag_entry->>'id'=i#>>'{}') then raise exception 'Tag unavailable' using errcode='22023';end if;end loop;
 for a in select value from jsonb_array_elements(c->'images') loop
 if a->>'path' is distinct from uid::text||'/'||(c->>'id')||'/'||(a->>'id')||'.webp' or a->>'thumbnailPath' is distinct from uid::text||'/'||(c->>'id')||'/'||(a->>'id')||'.thumb.webp' or jsonb_typeof(a->'width') is distinct from 'number' or jsonb_typeof(a->'height') is distinct from 'number' or jsonb_typeof(a->'alt') is distinct from 'string' or (a->>'width')::integer not between 1 and 16000 or (a->>'height')::integer not between 1 and 16000 or length(a->>'alt')>1000 then raise exception 'Invalid attachment' using errcode='22023';end if;
 if not exists(select 1 from storage.objects where bucket_id='constellation-images' and name=a->>'path') or not exists(select 1 from storage.objects where bucket_id='constellation-images' and name=a->>'thumbnailPath') then raise exception 'Attachment upload not confirmed' using errcode='22023';end if;end loop;
 select * into old from public.constellation_cards where id=(c->>'id')::uuid;if found and old.user_id<>uid then raise exception 'Card unavailable' using errcode='42501';end if;p:=c-'id'-'createdAt'-'updatedAt';
 insert into public.constellation_cards(id,user_id,payload) values((c->>'id')::uuid,uid,p) on conflict(id) do update set payload=excluded.payload,updated_at=clock_timestamp() where public.constellation_cards.user_id=uid and public.constellation_cards.payload is distinct from excluded.payload;
 end loop;
 delete from public.constellation_cards where user_id=uid and id not in (select (value->>'id')::uuid from jsonb_array_elements(p_state->'cards'));
 delete from public.constellation_tags where user_id=uid and id not in (select (value->>'id')::uuid from jsonb_array_elements(p_state->'tags'));
 update public.constellation_versions set revision=revision+1 where user_id=uid returning revision into v;insert into public.constellation_commands values(uid,p_command_id,h,v);return v;
end $$;
revoke all on function public.save_constellations(bigint,uuid,jsonb) from public,anon;grant execute on function public.save_constellations(bigint,uuid,jsonb) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('constellation-images','constellation-images',false,8388608,array['image/webp']);
create policy constellation_upload on storage.objects for insert to authenticated with check(bucket_id='constellation-images' and (storage.foldername(name))[1]=(select auth.uid())::text and array_length(storage.foldername(name),1)=2 and (storage.foldername(name))[2] ~ '^[0-9a-f-]{36}$' and storage.filename(name) ~ '^[0-9a-f-]{36}(\.thumb)?\.webp$');
create policy constellation_image_read on storage.objects for select to authenticated using(bucket_id='constellation-images' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy constellation_image_remove on storage.objects for delete to authenticated using(bucket_id='constellation-images' and (storage.foldername(name))[1]=(select auth.uid())::text and not exists(select 1 from public.constellation_cards c cross join lateral jsonb_array_elements(c.payload->'images') a where c.user_id=auth.uid() and (a->>'path'=name or a->>'thumbnailPath'=name)));
